// Writes a C# class with one constant per goal key, so game code never hand-types goal keys.

using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using UnityEditor;

namespace PlaytestFunSdk.Editor
{
    static class PlaytestFunCodegen
    {
        /// <summary>First line of every generated file; files without it are never overwritten or deleted.</summary>
        internal const string Marker = "// Generated by PLAYTEST.FUN.";

        internal static string Generate(Playtest playtest, string ns = PlaytestFunEditorSettings.DefaultNamespace, string className = PlaytestFunEditorSettings.DefaultClassName)
        {
            var body = new List<string>
            {
                "/// <summary>Goal keys for PlaytestFun.Instance.Goal(...).</summary>",
                $"public static class {className}",
                "{",
                $"    public const string PlaytestId = \"{Escape(playtest.id)}\";",
            };
            if (!string.IsNullOrEmpty(playtest.versionLabel))
            {
                body.Add("    /// <summary>Version label of the playtest's build.</summary>");
                body.Add($"    public const string VersionLabel = \"{Escape(playtest.versionLabel)}\";");
            }

            var used = new HashSet<string> { "PlaytestId", "VersionLabel", className };
            foreach (var goal in playtest.goals ?? new Goal[0])
            {
                if (string.IsNullOrEmpty(goal.Key)) continue;
                var name = Identifier(goal.Key);
                for (int i = 2; !used.Add(name); ++i) name = Identifier(goal.Key) + i;

                body.Add("");
                var summary = OneLine(goal.Title);
                if (goal.Target != 0) summary += $" (target {goal.Target.ToString(CultureInfo.InvariantCulture)})";
                body.Add($"    /// <summary>{System.Security.SecurityElement.Escape(summary)}</summary>");
                body.Add($"    public const string {name} = \"{Escape(goal.Key)}\";");
                if (goal.Target != 0)
                    body.Add($"    public const double {name}Target = {goal.Target.ToString("R", CultureInfo.InvariantCulture)};");
            }
            body.Add("}");

            var sb = new StringBuilder();
            sb.Append(Marker).Append(" Do not edit: fetch and generate again (Tools > PLAYTEST.FUN).\n");
            sb.Append($"// Playtest: {OneLine(playtest.title)} ({OneLine(playtest.id)})\n\n");
            bool wrap = !string.IsNullOrEmpty(ns);
            if (wrap) sb.Append($"namespace {ns}\n{{\n");
            foreach (var line in body)
                sb.Append(wrap && line.Length > 0 ? "    " : "").Append(line).Append('\n');
            if (wrap) sb.Append("}\n");
            return sb.ToString();
        }

        /// <summary>Writes the constants for <paramref name="playtest"/>; returns an error or null.</summary>
        internal static string Write(Playtest playtest)
        {
            var opts = PlaytestFunEditorSettings.instance;
            var path = opts.OutputPath;
            if (File.Exists(path) && !IsGenerated(File.ReadAllText(path)))
                return $"{path} exists and was not generated by PLAYTEST.FUN. Pick another path.";

            // Moved: drop the old file so the class is not defined twice.
            var old = opts.lastGeneratedPath;
            if (!string.IsNullOrEmpty(old) && old != path && File.Exists(old) && IsGenerated(File.ReadAllText(old)))
                AssetDatabase.DeleteAsset(old);

            Directory.CreateDirectory(Path.GetDirectoryName(path));
            File.WriteAllText(path, Generate(playtest, opts.Namespace, opts.ClassName), new UTF8Encoding(false));
            AssetDatabase.ImportAsset(path);
            opts.lastGeneratedPath = path;
            opts.Save();
            if (opts.buildVersionFromPlaytest) ApplyBuildVersion(playtest);
            return null;
        }

        /// <summary>Sets Build Version in the shipped settings to the playtest's version label.</summary>
        static void ApplyBuildVersion(Playtest playtest)
        {
            var settings = PlaytestFunSettingsProvider.GetOrCreateSettings();
            if (string.IsNullOrEmpty(playtest.versionLabel) || settings.buildVersion == playtest.versionLabel) return;
            Undo.RecordObject(settings, "Set PLAYTEST.FUN build version");
            settings.buildVersion = playtest.versionLabel;
            EditorUtility.SetDirty(settings);
            AssetDatabase.SaveAssets();
        }

        /// <summary>Why Build Version does not match the playtest the constants were made for, or null.</summary>
        internal static string BuildVersionMismatch(string buildVersion, Playtest playtest) =>
            playtest == null || string.IsNullOrEmpty(playtest.versionLabel) || buildVersion == playtest.versionLabel
                ? null
                : $"Build Version is \"{buildVersion}\" but the playtest's version label is \"{playtest.versionLabel}\".";

        internal static bool IsGenerated(string code) => code != null && code.TrimStart('﻿').StartsWith(Marker);

        static readonly Regex PlaytestIdLine = new Regex(@"public const string PlaytestId = ""((?:[^""\\]|\\.)*)"";");

        /// <summary>The PlaytestId a generated file was made for, or null.</summary>
        internal static string ReadPlaytestId(string code)
        {
            var m = code == null ? null : PlaytestIdLine.Match(code);
            return m != null && m.Success ? m.Groups[1].Value.Replace("\\\"", "\"").Replace("\\\\", "\\") : null;
        }

        /// <summary>
        /// Why the generated file no longer matches the server or the settings, or null when it is current.
        /// <paramref name="regenerate"/> is the playtest to generate again from, when there is one.
        /// </summary>
        internal static string Staleness(string code, Playtest[] playtests, string settingsPlaytestId,
                                         string ns, string className, out Playtest regenerate)
        {
            regenerate = null;
            if (code == null || !IsGenerated(code)) return null;
            var id = ReadPlaytestId(code);
            var forFile = playtests?.FirstOrDefault(p => p.id == id);

            if (!string.IsNullOrEmpty(settingsPlaytestId) && id != settingsPlaytestId)
            {
                regenerate = playtests?.FirstOrDefault(p => p.id == settingsPlaytestId);
                return "The goal constants were generated for another playtest than the Playtest Id.";
            }
            if (playtests == null) return null;  // nothing fetched: cannot tell
            if (forFile == null) return "The playtest the goal constants were generated for is no longer on the server.";
            regenerate = forFile;
            if (Normalize(code) != Normalize(Generate(forFile, ns, className)))
                return "The goals changed on the server (or the generation options did).";
            regenerate = null;
            return null;
        }

        /// <summary>The playtest to generate for: the Playtest Id, or the only playtest. Null with an error otherwise.</summary>
        internal static Playtest Pick(Playtest[] playtests, string playtestId, out string error)
        {
            error = null;
            if (playtests == null || playtests.Length == 0) { error = "This game has no playtests yet."; return null; }
            if (!string.IsNullOrEmpty(playtestId))
            {
                var pt = playtests.FirstOrDefault(p => p.id == playtestId);
                if (pt == null) error = $"Playtest Id {playtestId} is not one of this game's playtests.";
                return pt;
            }
            if (playtests.Length == 1) return playtests[0];
            error = "This game has several playtests. Pick one with \"Use as Playtest Id\" in Project Settings > PLAYTEST.FUN.";
            return null;
        }

        /// <summary>"collect_points" → "CollectPoints"; a leading digit gets an underscore.</summary>
        internal static string Identifier(string key)
        {
            var sb = new StringBuilder();
            bool upper = true;
            foreach (var ch in key)
            {
                if (!char.IsLetterOrDigit(ch) || ch > 127) { upper = true; continue; }
                sb.Append(upper ? char.ToUpperInvariant(ch) : ch);
                upper = false;
            }
            if (sb.Length == 0 || char.IsDigit(sb[0])) sb.Insert(0, '_');
            return sb.ToString();
        }

        static string Normalize(string s) => s.TrimStart('﻿').Replace("\r\n", "\n").TrimEnd();
        static string Escape(string s) => (s ?? "").Replace("\\", "\\\\").Replace("\"", "\\\"");
        static string OneLine(string s) => (s ?? "").Replace('\r', ' ').Replace('\n', ' ');
    }
}
